17	import {
18	    Button,
19	    Dialog,
20	    DialogActions,
21	    DialogContent,
22	    DialogDescription,
23	    DialogPortal,
24	    DialogTitle,
25	    Input,
26	} from '@bloodhoundenterprise/doodleui';
27	import React, { useCallback, useState } from 'react';
28	
29	const ConfirmationDialog: React.FC<{
30	    open: boolean;
31	    title: string;
32	    text: string | JSX.Element;
33	    onCancel: () => void;
34	    onConfirm: () => void;
35	    challengeTxt?: string;
36	    isLoading?: boolean;
37	    error?: string;
38	}> = ({ open, title, text, onCancel, isLoading, error, challengeTxt = '', onConfirm }) => {
39	    const [challengeTxtReply, setChallengeTxtReply] = useState<string>('');
40	
41	    const handleClose = useCallback(() => {
42	        onCancel();
43	        setTimeout(() => {
44	            setChallengeTxtReply('');
45	        }, 1000);
46	    }, [onCancel]);
47	
48	    const handleConfirm = useCallback(() => {
49	        onConfirm();
50	        setTimeout(() => {
51	            setChallengeTxtReply('');
52	        }, 1000);
53	    }, [onConfirm]);
54	
55	    return (
56	        <Dialog open={open} data-testid='confirmation-dialog'>
57	            <DialogPortal>
58	                <DialogContent>
59	                    <DialogTitle className='text-lg'>{title}</DialogTitle>
60	                    <DialogDescription className='text-lg'>{text}</DialogDescription>
61	                    {challengeTxt && (
62	                        <DialogDescription asChild className='text-sm'>
63	                            <div>
64	                                Please input "{challengeTxt}" prior to clicking confirm.
65	                                <Input
66	                                    placeholder={challengeTxt}
67	                                    className='border-t-0 border-l-0 border-r-0 rounded-none border-black dark:border-white bg-transparent dark:bg-transparent placeholder-neutral-dark-10 dark:placeholder-neutral-light-10 focus-visible:ring-0 focus-visible:ring-offset-0 pl-2'
68	                                    onChange={(e) => setChallengeTxtReply(e.target.value)}
69	                                    value={challengeTxtReply}
70	                                    data-testid='confirmation-dialog_challenge-text'
71	                                />
72	                            </div>
73	                        </DialogDescription>
74	                    )}
75	                    <DialogActions>
76	                        {error && <p className='content-center text-error text-xs mt-[3px]'>{error}</p>}
77	                        <Button
78	                            variant='tertiary'
79	                            onClick={handleClose}
80	                            disabled={isLoading}
81	                            data-testid='confirmation-dialog_button-no'>
82	                            Cancel
83	                        </Button>
84	                        <Button
85	                            onClick={handleConfirm}
86	                            disabled={isLoading || challengeTxt.toLowerCase() !== challengeTxtReply.toLowerCase()}
87	                            data-testid='confirmation-dialog_button-yes'>
88	                            Confirm
89	                        </Button>
90	                    </DialogActions>
91	                </DialogContent>
92	            </DialogPortal>
93	        </Dialog>
94	    );
95	};
96	
97	export default ConfirmationDialog;
