import {
    Button,
    Card,
    CardTitle,
    createColumnHelper,
    DataTable,
    Dialog,
    DialogActions,
    DialogContent,
    DialogDescription,
    DialogPortal,
    DialogTitle,
    Input,
    TableCell,
    TableRow,
} from '@bloodhoundenterprise/doodleui';
import { Extension } from 'js-client-library';
import { Trash } from 'lucide-react';
import { useEffect, useState } from 'react';
import { useMutation } from 'react-query';
import { SearchInput } from '../../components';
import { useExtensionsQuery } from '../../hooks';
import { useNotifications } from '../../providers';
import { apiClient } from '../../utils';

const columnHelper = createColumnHelper<Extension>();

export const getColumns = (onDeleteClick: (extension: Extension) => void) => [
    columnHelper.accessor('name', {
        id: 'name',
        header: () => <span className='pl-6'>Name</span>,
        cell: ({ row }) => <span className='pl-6'>{row.original.name}</span>,
    }),
    columnHelper.accessor('version', {
        id: 'version',
        header: () => <span className=''>Version</span>,
        cell: ({ row }) => <span>{row.original.version}</span>,
    }),
    columnHelper.accessor('delete', {
        id: 'delete-item',
        // This is a hack to make the column header not visible but still accessible for screen readers
        // Also keeps last column consistent width when no rows are rendered
        header: () => <span className='opacity-0'>Delete</span>,
        cell: ({ row }) => (
            <button
                aria-label={`Delete ${row.original.name}`}
                disabled={row.original.is_builtin}
                onClick={() => onDeleteClick(row.original)}
                className='disabled:opacity-50 disabled:cursor-not-allowed'>
                <Trash size={18} />
            </button>
        ),
        size: 0,
    }),
];

export const ERROR_MESSAGE = 'There was an error fetching extensions';
export const LOADING_MESSAGE = 'Loading extensions...';
export const NO_DATA_MESSAGE = 'There are currently no active extensions';
export const NO_SEARCH_RESULTS_MESSAGE = 'No extensions match your search terms';

const TABLE_CELL_HEIGHT = 57;
const TABLE_HEADER_HEIGHT = 52;
const EMPTY_STATE_HEIGHT = `${TABLE_HEADER_HEIGHT + TABLE_CELL_HEIGHT * 2}px`;

const DeleteExtensionDialog: React.FC<{
    open: boolean;
    extension: Extension | null;
    isLoading?: boolean;
    onCancel: () => void;
    onConfirm: () => void;
}> = ({ open, extension, isLoading, onCancel, onConfirm }) => {
    const [confirmText, setConfirmText] = useState('');

    // Reset the confirmation input whenever the dialog is opened so that a
    // previously typed value is never carried over into a new confirmation.
    useEffect(() => {
        if (open) {
            setConfirmText('');
        }
    }, [open, extension?.id]);

    const extensionName = extension?.name ?? '';
    const isMatch = confirmText === extensionName;

    return (
        <Dialog open={open} data-testid='delete-extension-dialog'>
            <DialogPortal>
                <DialogContent>
                    <DialogTitle className='text-lg'>Delete selected extension</DialogTitle>
                    <DialogDescription asChild className='text-lg'>
